INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"4ccdb541-1dec-52b8-89ef-022494c0af6d","title":"Life Orientation · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 11","questions":[{"question":"A learner is sleeping too little to keep studying longer. What is the most constructive response?","options":["Assume less sleep always improves memory","Use unverified substances to stay awake","Abandon all schoolwork permanently","Adjust the plan to include rest and seek support with workload"],"correct_index":3,"explanation":"Rest supports attention and learning. A realistic schedule and timely support are more sustainable than repeated exhaustion.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What does work ethics include?","options":["Concealing mistakes from everyone","Using others' work without credit","Reliability, honesty and respect for responsibilities","Ignoring agreed safety procedures"],"correct_index":2,"explanation":"Ethical conduct involves accountability and consideration of others. Ask for help and correct errors rather than hiding them.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A learner rereads notes but struggles in tests. What is a useful change?","options":["Only buy more highlighters","Practise retrieval and timed questions, then review errors","Stop checking answers","Avoid difficult topics entirely"],"correct_index":1,"explanation":"Practice reveals what can be recalled and applied under test conditions. Feedback helps target the next study session.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why should a study plan be revised after a practice test?","options":["One score determines lifelong ability","The original plan must never change","Errors provide evidence about what needs more attention","Only correct answers deserve review"],"correct_index":2,"explanation":"Use mistakes diagnostically: identify the concept, practise it and check again. A score is information about that attempt, not a fixed label.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Two study plans use equal hours: one rereads all topics; the other uses error analysis and timed practice. How should effectiveness be evaluated?","options":["Count page colours as the sole measure.","Assume equal hours guarantee equal understanding.","Compare progress on relevant practice tasks and adjust for remaining weaknesses.","Choose the plan with the longest title."],"correct_index":2,"explanation":"Study effectiveness depends on learning outcomes, not hours alone. Relevant retrieval and application tasks reveal whether understanding and exam performance improve and where further attention is needed.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lo"],"metadata":{"term":2,"focus":"Mixed revision: Lifestyle choices and career competence; Human rights, moral reasoning and exam planning","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"f65162cf-0a4a-5d85-b917-7125cf5deea7","title":"Life Orientation · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 11","questions":[{"question":"Which action helps challenge unequal power in a school group?","options":["Let one member silence everyone","Treat intimidation as leadership","Give members safe ways to speak and respond fairly to concerns","Dismiss every complaint automatically"],"correct_index":2,"explanation":"Fair participation and accountability can reduce harmful power imbalances. Address intimidation through appropriate school support processes.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which community action supports responsible citizenship?","options":["Dump waste elsewhere at night","Report illegal dumping through suitable channels and help plan safe prevention","Ignore vulnerable residents","Post private accusations without evidence"],"correct_index":1,"explanation":"Responsible action uses safe, lawful channels and cooperation. Prevention should address causes and include affected people.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A learner rereads notes but struggles in tests. What is a useful change?","options":["Only buy more highlighters","Practise retrieval and timed questions, then review errors","Stop checking answers","Avoid difficult topics entirely"],"correct_index":1,"explanation":"Practice reveals what can be recalled and applied under test conditions. Feedback helps target the next study session.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why should a study plan be revised after a practice test?","options":["One score determines lifelong ability","The original plan must never change","Errors provide evidence about what needs more attention","Only correct answers deserve review"],"correct_index":2,"explanation":"Use mistakes diagnostically: identify the concept, practise it and check again. A score is information about that attempt, not a fixed label.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Two study plans use equal hours: one rereads all topics; the other uses error analysis and timed practice. How should effectiveness be evaluated?","options":["Count page colours as the sole measure.","Assume equal hours guarantee equal understanding.","Compare progress on relevant practice tasks and adjust for remaining weaknesses.","Choose the plan with the longest title."],"correct_index":2,"explanation":"Study effectiveness depends on learning outcomes, not hours alone. Relevant retrieval and application tasks reveal whether understanding and exam performance improve and where further attention is needed.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lo"],"metadata":{"term":3,"focus":"Mixed revision: Power relations and environmental responsibility; Human rights, moral reasoning and exam planning","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"b16562ee-cdbe-534a-9106-4344ca0ba853","title":"Life Orientation · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 11","questions":[{"question":"Which action helps challenge unequal power in a school group?","options":["Let one member silence everyone","Treat intimidation as leadership","Give members safe ways to speak and respond fairly to concerns","Dismiss every complaint automatically"],"correct_index":2,"explanation":"Fair participation and accountability can reduce harmful power imbalances. Address intimidation through appropriate school support processes.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which community action supports responsible citizenship?","options":["Dump waste elsewhere at night","Report illegal dumping through suitable channels and help plan safe prevention","Ignore vulnerable residents","Post private accusations without evidence"],"correct_index":1,"explanation":"Responsible action uses safe, lawful channels and cooperation. Prevention should address causes and include affected people.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which is a transferable work skill?","options":["Communicating clearly and collaborating on tasks","Memorising one person's phone number only","Refusing all feedback","Avoiding every new problem"],"correct_index":0,"explanation":"Transferable skills can be used across roles and settings. Learners can develop them through projects, responsibilities and reflection.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A job advertisement requires a skill the learner has not yet developed. What is a useful next step?","options":["Invent experience on the CV","Identify credible training and practise the skill while checking other requirements","Assume every training advert is legitimate","Pay anyone promising a guaranteed job"],"correct_index":1,"explanation":"Compare the gap with reliable training options and develop evidence of competence. Honest applications protect credibility.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A learner's longer study hours reduce sleep and practice-test performance. Which revision best uses the evidence?","options":["Add more late-night hours regardless of the results.","Assume exhaustion proves successful learning.","Rebalance focused study and rest, review errors and seek support with workload.","Stop reviewing performance because the plan is already written."],"correct_index":2,"explanation":"A plan should respond to outcomes and wellbeing. Shorter focused sessions, rest and targeted error review can be evaluated through subsequent progress rather than equating hours alone with learning.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lo"],"metadata":{"term":4,"focus":"Mixed revision: Power relations and environmental responsibility; Lifestyle choices and career competence","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=bpueOI1aTK4%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8971d82a-8ff9-5838-aaca-d90732dc8c70","title":"English HL · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 11","questions":[{"question":"Which word creates an unjustifiably exclusive claim?","options":["Only","Poster","Three","Beneath"],"correct_index":0,"explanation":"Only excludes all other routes to success. The passage provides no evidence for such a broad claim.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which revision makes the slogan more defensible?","options":["Guaranteed success for every learner","No effort needed for top marks","All other learning is useless","A study tool designed to support your preparation"],"correct_index":3,"explanation":"The revised wording describes intended support without unsupported guarantees or dismissing other learning routes.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"What does its silence seemed louder suggest?","options":["The watch is literally ringing louder","The narrator has measured sound levels","The watch's emotional significance is strongly felt despite its silence","The drawer contains a loudspeaker"],"correct_index":2,"explanation":"The apparent contradiction conveys emotional intensity. Explain the contextual effect rather than insisting on a literal sound.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Why should the narrator's motive for closing the drawer remain qualified?","options":["The text states every thought explicitly","A first-person narrator can never be interpreted","The sister has already explained it","The action suggests attachment but does not state the full motive"],"correct_index":3,"explanation":"Inference can identify possibilities supported by details while recognising that the narrator leaves some meaning unstated.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Which evaluation best explains why gently matters in the closing action?","options":["It proves the narrator has agreed to give the watch away.","It establishes the watch's exact financial value.","It supports a careful, emotionally weighted response without proving the narrator's full motive.","It shows that the drawer is broken."],"correct_index":2,"explanation":"The manner of closing contributes to tone and suggests care or restraint. It enriches the attachment reading but does not state a final decision or a complete motive.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","enhl"],"metadata":{"term":2,"focus":"Mixed revision: Advertising claims and critical literacy; Narrative perspective and imagery","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"a94c0e06-34ae-558d-9775-b02a7cec3f68","title":"English HL · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 11","questions":[{"question":"What contrast is introduced by yet?","options":["The library had no books","The survey happened before the school existed","Every learner stopped travelling","Longer opening hours did not lead to much higher attendance"],"correct_index":3,"explanation":"Yet signals an unexpected outcome compared with the likely expectation that more hours would increase use.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"What does an unlocked door represent in the final sentence?","options":["Proof that all learners can attend","An instruction to remove the door","A narrow idea of access based only on physical opening","A literal taxi timetable"],"correct_index":2,"explanation":"The image highlights the difference between formal availability and practical access. Transport makes the distinction meaningful.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"What does its silence seemed louder suggest?","options":["The watch is literally ringing louder","The narrator has measured sound levels","The watch's emotional significance is strongly felt despite its silence","The drawer contains a loudspeaker"],"correct_index":2,"explanation":"The apparent contradiction conveys emotional intensity. Explain the contextual effect rather than insisting on a literal sound.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Why should the narrator's motive for closing the drawer remain qualified?","options":["The text states every thought explicitly","A first-person narrator can never be interpreted","The sister has already explained it","The action suggests attachment but does not state the full motive"],"correct_index":3,"explanation":"Inference can identify possibilities supported by details while recognising that the narrator leaves some meaning unstated.","stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Which evaluation best explains why gently matters in the closing action?","options":["It proves the narrator has agreed to give the watch away.","It establishes the watch's exact financial value.","It supports a careful, emotionally weighted response without proving the narrator's full motive.","It shows that the drawer is broken."],"correct_index":2,"explanation":"The manner of closing contributes to tone and suggests care or restraint. It enriches the attachment reading but does not state a final decision or a complete motive.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"I kept Father's old watch in a drawer. It no longer told the time, but each evening its silence seemed louder. When my sister asked for it, I closed the drawer gently."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","enhl"],"metadata":{"term":3,"focus":"Mixed revision: Argument, inference and summary; Narrative perspective and imagery","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"02de731f-7ff1-5297-bde4-de013bbf3e4f","title":"English HL · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 11","questions":[{"question":"What contrast is introduced by yet?","options":["The library had no books","The survey happened before the school existed","Every learner stopped travelling","Longer opening hours did not lead to much higher attendance"],"correct_index":3,"explanation":"Yet signals an unexpected outcome compared with the likely expectation that more hours would increase use.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"What does an unlocked door represent in the final sentence?","options":["Proof that all learners can attend","An instruction to remove the door","A narrow idea of access based only on physical opening","A literal taxi timetable"],"correct_index":2,"explanation":"The image highlights the difference between formal availability and practical access. Transport makes the distinction meaningful.","stimulus":"The school extended library hours, yet attendance barely changed. In a survey, many learners said the last taxi left before closing time. Access, the librarian realised, was more than an unlocked door.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"What persuasive function do the smiling learners mainly serve?","options":["They establish a controlled comparison","They associate the app with positive outcomes and satisfaction","They prove every user succeeds","They provide the missing results dataset"],"correct_index":1,"explanation":"Visual endorsement can create positive associations. It does not by itself establish effectiveness or causation.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"What evidence would best help evaluate the claim?","options":["More smiling photographs alone","A larger slogan","Reliable results with clear methods and an appropriate comparison","An unrelated celebrity's favourite colour"],"correct_index":2,"explanation":"Evidence needs to address the claim, including how outcomes were measured and compared. Design and context matter.","stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Would replacing only path with a useful tool solve every credibility problem? Choose the best answer.","options":["Yes; modest wording makes all performance claims automatically true.","No; all advertising is necessarily false.","It reduces the absolute claim, but claims of effectiveness still need evidence.","Yes; smiling faces are sufficient results data."],"correct_index":2,"explanation":"A qualified slogan is more defensible than an exclusive guarantee, yet the text still supplies no comparison or results. Wording and evidential support are separate aspects of credibility.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Our study app is the only path to success, says a poster. Beneath the slogan, three smiling learners hold certificates. No results data or comparison is provided."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","enhl"],"metadata":{"term":4,"focus":"Mixed revision: Argument, inference and summary; Advertising claims and critical literacy","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=4WZaNZmHP38%3d&tabid=3205&portalid=0&mid=10754"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"e82cf7b1-fd1a-51e7-b27c-68a691a40a93","title":"Afrikaans HL · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 11","questions":[{"question":"Watter woord maak die aanspraak uitsluitend?","options":["Drie","Enigste","Plakkaat","Sertifikate"],"correct_index":1,"explanation":"Enigste sluit ander moontlike paaie uit. Die teks bied nie bewyse vir so 'n wye aanspraak nie.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Watter herskrywing is meer verantwoordbaar?","options":["'n Hulpmiddel wat jou studievoorbereiding ondersteun","Sukses word vir almal gewaarborg","Geen werk is nodig nie","Alle ander leer is nutteloos"],"correct_index":0,"explanation":"Die herskrywing beskryf ondersteuning sonder 'n ongegronde waarborg of uitsluiting van ander leerwyses.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Wat suggereer sy stilte harder?","options":["Die horlosie lui letterlik harder","Daar is 'n luidspreker in die laai","Die verteller meet klankvlakke","Die horlosie se emosionele betekenis bly sterk"],"correct_index":3,"explanation":"Die skynbare teenstrydigheid beklemtoon gevoel eerder as 'n letterlike geluid.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Waarom moet die verteller se motief versigtig geïnterpreteer word?","options":["Die handeling suggereer gehegtheid, maar die volle motief word nie uitgespel nie","Elke gedagte word volledig verduidelik","Die suster vertel die hele verhaal","'n Eerstepersoonsverhaal kan nie ontleed word nie"],"correct_index":0,"explanation":"Afleidings moet op besonderhede steun en erken waar die teks inligting ooplaat.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Hoe dra saggies tot die slot se uitwerking by?","options":["Dit bewys dat die horlosie weggegee word.","Dit bepaal die horlosie se presiese geldwaarde.","Dit suggereer sorg of terughouding sonder om die verteller se volle motief te bewys.","Dit wys dat die laai stukkend is."],"correct_index":2,"explanation":"Die manier waarop die laai toegemaak word, dra emosionele betekenis. Dit ondersteun 'n versigtige interpretasie van gehegtheid, maar gee nie 'n volledige verklaring of finale besluit nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","afhl"],"metadata":{"term":2,"focus":"Mixed revision: Advertensies en kritiese geletterdheid; Verteller en emosionele betekenis","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"91830717-dd8d-5211-ac3e-32d484e9741f","title":"Afrikaans HL · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 11","questions":[{"question":"Watter teenstelling dui maar aan?","options":["Langer ure lei nie tot veel beter bywoning nie","Die biblioteek het geen boeke nie","Die opname is eeue oud","Geen leerder reis ooit nie"],"correct_index":0,"explanation":"Maar wys dat die uitkoms verskil van wat 'n mens waarskynlik sou verwag.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Wat verteenwoordig 'n oop deur in die slotsin?","options":["Gewaarborgde toegang vir elke leerder","Die prys van vervoer","Die uitslag van 'n toets","Slegs die fisiese beskikbaarheid van die ruimte"],"correct_index":3,"explanation":"Die beeld kontrasteer formele beskikbaarheid met praktiese toegang. Die vervoerprobleem verduidelik die verskil.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Wat suggereer sy stilte harder?","options":["Die horlosie lui letterlik harder","Daar is 'n luidspreker in die laai","Die verteller meet klankvlakke","Die horlosie se emosionele betekenis bly sterk"],"correct_index":3,"explanation":"Die skynbare teenstrydigheid beklemtoon gevoel eerder as 'n letterlike geluid.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Waarom moet die verteller se motief versigtig geïnterpreteer word?","options":["Die handeling suggereer gehegtheid, maar die volle motief word nie uitgespel nie","Elke gedagte word volledig verduidelik","Die suster vertel die hele verhaal","'n Eerstepersoonsverhaal kan nie ontleed word nie"],"correct_index":0,"explanation":"Afleidings moet op besonderhede steun en erken waar die teks inligting ooplaat.","stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Hoe dra saggies tot die slot se uitwerking by?","options":["Dit bewys dat die horlosie weggegee word.","Dit bepaal die horlosie se presiese geldwaarde.","Dit suggereer sorg of terughouding sonder om die verteller se volle motief te bewys.","Dit wys dat die laai stukkend is."],"correct_index":2,"explanation":"Die manier waarop die laai toegemaak word, dra emosionele betekenis. Dit ondersteun 'n versigtige interpretasie van gehegtheid, maar gee nie 'n volledige verklaring of finale besluit nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Ek bêre Pa se ou horlosie in 'n laai. Dit wys nie meer die tyd nie, maar elke aand voel sy stilte harder. Toe my suster daarna vra, maak ek die laai saggies toe."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","afhl"],"metadata":{"term":3,"focus":"Mixed revision: Argument en samevatting; Verteller en emosionele betekenis","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"408cf613-573b-5a57-aedc-3d5ac8c10d9e","title":"Afrikaans HL · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 11","questions":[{"question":"Watter teenstelling dui maar aan?","options":["Langer ure lei nie tot veel beter bywoning nie","Die biblioteek het geen boeke nie","Die opname is eeue oud","Geen leerder reis ooit nie"],"correct_index":0,"explanation":"Maar wys dat die uitkoms verskil van wat 'n mens waarskynlik sou verwag.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Wat verteenwoordig 'n oop deur in die slotsin?","options":["Gewaarborgde toegang vir elke leerder","Die prys van vervoer","Die uitslag van 'n toets","Slegs die fisiese beskikbaarheid van die ruimte"],"correct_index":3,"explanation":"Die beeld kontrasteer formele beskikbaarheid met praktiese toegang. Die vervoerprobleem verduidelik die verskil.","stimulus":"Die skool verleng die biblioteek se ure, maar bywoning verander min. In 'n opname sê baie leerders dat die laaste taxi voor sluitingstyd vertrek. Toegang beteken dus meer as 'n oop deur.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Wat is die oorredende funksie van die glimlaggende leerders?","options":["Hulle bewys alle gebruikers slaag","Hulle vorm 'n volledige ondersoek","Hulle verbind die produk met positiewe uitkomste","Hulle vervang alle uitslagdata"],"correct_index":2,"explanation":"Die beeld skep 'n positiewe assosiasie, maar bewys nie die produk se effektiwiteit nie.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Watter bykomende inligting sal die aanspraak die beste help toets?","options":["Net nog glimlaggende foto's","'n Groter slagspreuk","'n Ander agtergrondkleur","Betroubare uitslae met duidelike metodes en 'n gepaste vergelyking"],"correct_index":3,"explanation":"Bewyse moet by die aanspraak pas. Metodes en vergelykbaarheid bepaal hoe sterk die gevolgtrekking kan wees.","stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Sal die vervanging van enigste pad met nuttige hulpmiddel elke geloofwaardigheidsprobleem oplos?","options":["Ja; beskeie taal maak enige aanspraak vanself waar.","Nee; elke advertensie is noodwendig vals.","Nee; die aanspraak is minder absoluut, maar doeltreffendheid verg steeds bewyse.","Ja; glimlagte vervang betroubare uitslae."],"correct_index":2,"explanation":"Versigtige woordkeuse verminder die oordrewe waarborg, maar skep nie ontbrekende resultate of vergelykings nie. Die sterkte van taal en die sterkte van bewyse moet afsonderlik beoordeel word.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Ons toepassing is die enigste pad na sukses, verklaar 'n plakkaat. Drie glimlaggende leerders hou sertifikate vas. Geen uitslagdata of vergelyking word verskaf nie."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","afhl"],"metadata":{"term":4,"focus":"Mixed revision: Argument en samevatting; Advertensies en kritiese geletterdheid","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=--b2JtSIDTc%3d&tabid=3205&portalid=0&mid=10754"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"cfe50870-576c-5db6-9998-619757d4b332","title":"isiXhosa HL · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"isiXhosa HL","grade":"Grade 11","questions":[{"question":"Yeyiphi eyona ngxaki kubungqina?","options":["Akukho mntu unokufunda kwinkqubo.","Amanqaku awanakuze alinganiswe.","Amava omfundi omnye awanele ukungqina ifuthe kubo bonke.","Zonke iintengiso zibubuxoki."],"correct_index":2,"explanation":"Ubungqina bunomda kuba isampuli incinci kwaye akukho thelekiso lunikiweyo. Oku akuthethi ukuba inkqubo ayinakunceda mntu.","stimulus":"Umbutho uthi inkqubo yawo inyusa amanqaku. Kwisibhengezo kusetyenziswa impendulo yomfundi omnye. Akunikwa amanqaku angaphambi kwenkqubo okanye iqela lokuthelekisa.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Kutheni kufuneka kuqwalaselwe injongo yombhali?","options":["Injongo ithetha ukuba onke amabango ayinyaniso.","Usenokuba ufuna ukuthengisa inkqubo nokugxininisa izibonelelo.","Injongo yombhali isusa imfuneko yobungqina.","Umbhali akanakukhetha ulwazi."],"correct_index":1,"explanation":"Ukuqonda injongo yokuthengisa kunceda ukubuza ukuba loluphi ulwazi olukhethiweyo okanye olushiyiweyo.","stimulus":"Umbutho uthi inkqubo yawo inyusa amanqaku. Kwisibhengezo kusetyenziswa impendulo yomfundi omnye. Akunikwa amanqaku angaphambi kwenkqubo okanye iqela lokuthelekisa.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Yintoni umahluko obalulekileyo?","options":["Umbalisi uthi uza kuhamba kodwa uyema alinde.","Isitshixo sitshintsha sibe yileta.","Amanyathelo afika kwangoko.","Umnyango uyathetha."],"correct_index":0,"explanation":"Umahluko phakathi kwesicwangciso nesenzo unokutyhila ukungaqiniseki okanye umnqweno wokuba kuze umntu.","stimulus":"Ndabeka isitshixo etafileni. Bendithe ndiza kuhamba ndingajonganga ngasemva. Kodwa ndema emnyango ndalinda, ndimamele amanyathelo awayengafiki.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Leliphi ilungelo lokutolika elixhaswayo?","options":["Umbalisi akaze alinde nabani na.","Ukulinda kunokubonisa ukuba ukuhamba kunzima kuye.","Isitshixo singqina ukuba indlu iyatsha.","Umntu olindelweyo ngokuqinisekileyo ngumntakwabo."],"correct_index":1,"explanation":"Ukutolika okuhle kusondela kwiinkcukacha zesicatshulwa kwaye kuvume ukuba ulwazi oluthile alunikiwanga.","stimulus":"Ndabeka isitshixo etafileni. Bendithe ndiza kuhamba ndingajonganga ngasemva. Kodwa ndema emnyango ndalinda, ndimamele amanyathelo awayengafiki.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Kutheni umahluko phakathi kwesithembiso sokuhamba nokulinda usebenza kakuhle?","options":["Ungqina ukuba umbalisi akazange afune ukuhamba.","Usixelela igama lomntu olindelweyo.","Uveza ukungqubana kwesigqibo nesenzo, kungachazwanga yonke imbangela.","Ubonisa ukuba izitshixo zinokuthetha."],"correct_index":2,"explanation":"Ukuma nokulinda emva kokuthi uza kuhamba kwakha ukungaqiniseki. Loo mahluko uvumela ukutolika okuxhaswayo ngaphandle kokwenza ibali elingekho kwisicatshulwa.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Ndabeka isitshixo etafileni. Bendithe ndiza kuhamba ndingajonganga ngasemva. Kodwa ndema emnyango ndalinda, ndimamele amanyathelo awayengafiki."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","xhhl"],"metadata":{"term":2,"focus":"Mixed revision: Ukufunda ngeliso 